Fixpoint fbnd {R} (B : Z) (L : mled) (t : M R) {struct t} : Prop :=
  match t with
  | SRet _ => True
  | SVis (EPeek _ _ _) k => forall v, fbnd B L (k v)
  | SVis (EUndef _) _ => True
  | SVis e k => BOUND L e B /\ forall a, answer_ok L e a = true -> fbnd B (event_post L e a) (k a)
  end.

