Fixpoint fbnd8 {R} (B : Z) (L : mled) (t : M R) {struct t} : Prop :=
  match t with
  | SRet _ => True
  | SVis (EPeek _ _ _) k => forall v, 0 <= v < 256 -> fbnd8 B L (k v)
  | SVis (EUndef _) _ => True
  | SVis e k => BOUND L e B /\ forall a, answer_ok L e a = true -> fbnd8 B (event_post L e a) (k a)
  end.

