Lemma fqtree_bind {R S} B (t : M R) (f : R -> M S) Post Q L :
  fqtree B L t Post -> (forall L' r, Post L' r -> fqtree B L' (f r) Q) -> fqtree B L (sbind t f) Q.
Proof.
